package secrets

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"syscall"

	"filippo.io/age"
	"github.com/nogo/herald/internal/config"
)

// Store manages an age-encrypted secrets file.
type Store struct {
	keyPath     string // path to age.key
	secretsPath string // path to secrets.age
}

// NewStore creates a Store rooted at dataDir.
func NewStore(dataDir string) *Store {
	return &Store{
		keyPath:     filepath.Join(dataDir, "age.key"),
		secretsPath: filepath.Join(dataDir, "secrets.age"),
	}
}

// Init generates the age key if it doesn't exist. If the key file has
// wrong permissions it fixes them and logs a warning.
func (s *Store) Init() error {
	info, err := os.Stat(s.keyPath)
	if err == nil {
		if info.Mode().Perm() != 0600 {
			slog.Warn("age key has insecure permissions, fixing", "path", s.keyPath, "mode", info.Mode().Perm())
			if err := os.Chmod(s.keyPath, 0600); err != nil {
				return fmt.Errorf("fixing age key permissions: %w", err)
			}
		}
		return nil
	}
	if !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("checking age key %s: %w", s.keyPath, err)
	}

	if err := os.MkdirAll(filepath.Dir(s.keyPath), 0700); err != nil {
		return fmt.Errorf("creating data directory: %w", err)
	}

	identity, err := age.GenerateX25519Identity()
	if err != nil {
		return fmt.Errorf("generating age key: %w", err)
	}

	// O_EXCL prevents overwriting if two processes race to init.
	f, err := os.OpenFile(s.keyPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err != nil {
		return fmt.Errorf("creating age key file: %w", err)
	}
	defer f.Close()

	if _, err := fmt.Fprintln(f, identity.String()); err != nil {
		return fmt.Errorf("writing age key: %w", err)
	}
	return nil
}

func (s *Store) loadIdentity() (*age.X25519Identity, error) {
	data, err := os.ReadFile(s.keyPath)
	if err != nil {
		return nil, fmt.Errorf("reading age key %s: %w", s.keyPath, err)
	}
	identity, err := age.ParseX25519Identity(strings.TrimSpace(string(data)))
	if err != nil {
		return nil, fmt.Errorf("parsing age key: %w", err)
	}
	return identity, nil
}

// withLock acquires an exclusive flock on a lock file for the duration of fn.
func (s *Store) withLock(fn func() error) error {
	lockPath := s.secretsPath + ".lock"
	lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0600)
	if err != nil {
		return fmt.Errorf("opening lock file: %w", err)
	}
	defer lf.Close()

	if err := syscall.Flock(int(lf.Fd()), syscall.LOCK_EX); err != nil {
		return fmt.Errorf("acquiring secrets lock: %w", err)
	}
	defer syscall.Flock(int(lf.Fd()), syscall.LOCK_UN) //nolint:errcheck

	return fn()
}

func (s *Store) readSecrets() (map[string]string, error) {
	data, err := os.ReadFile(s.secretsPath)
	if errors.Is(err, os.ErrNotExist) {
		return make(map[string]string), nil
	}
	if err != nil {
		return nil, fmt.Errorf("reading secrets file: %w", err)
	}

	identity, err := s.loadIdentity()
	if err != nil {
		return nil, err
	}

	r, err := age.Decrypt(bytes.NewReader(data), identity)
	if err != nil {
		return nil, fmt.Errorf("cannot decrypt secrets store: %w. Is the age key correct?", err)
	}

	var secrets map[string]string
	if err := json.NewDecoder(r).Decode(&secrets); err != nil {
		return nil, fmt.Errorf("decoding secrets: %w", err)
	}
	return secrets, nil
}

func (s *Store) writeSecrets(secrets map[string]string) error {
	identity, err := s.loadIdentity()
	if err != nil {
		return err
	}

	jsonData, err := json.Marshal(secrets)
	if err != nil {
		return fmt.Errorf("encoding secrets: %w", err)
	}

	tmpPath := s.secretsPath + ".tmp"
	f, err := os.OpenFile(tmpPath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0600)
	if err != nil {
		return fmt.Errorf("creating temp secrets file: %w", err)
	}

	w, err := age.Encrypt(f, identity.Recipient())
	if err != nil {
		f.Close()
		os.Remove(tmpPath)
		return fmt.Errorf("initializing encryption: %w", err)
	}

	if _, err := w.Write(jsonData); err != nil {
		f.Close()
		os.Remove(tmpPath)
		return fmt.Errorf("writing encrypted data: %w", err)
	}

	if err := w.Close(); err != nil {
		f.Close()
		os.Remove(tmpPath)
		return fmt.Errorf("finalizing encryption: %w", err)
	}

	if err := f.Close(); err != nil {
		os.Remove(tmpPath)
		return fmt.Errorf("closing temp file: %w", err)
	}

	return os.Rename(tmpPath, s.secretsPath)
}

// Set adds or updates a secret.
func (s *Store) Set(key, value string) error {
	return s.withLock(func() error {
		secrets, err := s.readSecrets()
		if err != nil {
			return err
		}
		secrets[key] = value
		return s.writeSecrets(secrets)
	})
}

// Get retrieves a secret value by key.
func (s *Store) Get(key string) (string, error) {
	secrets, err := s.readSecrets()
	if err != nil {
		return "", err
	}
	val, ok := secrets[key]
	if !ok {
		return "", fmt.Errorf("secret '%s' not found in store", key)
	}
	return val, nil
}

// List returns all secret keys sorted alphabetically.
func (s *Store) List() ([]string, error) {
	secrets, err := s.readSecrets()
	if err != nil {
		return nil, err
	}
	keys := make([]string, 0, len(secrets))
	for k := range secrets {
		keys = append(keys, k)
	}
	slices.Sort(keys)
	return keys, nil
}

// Delete removes a secret. Returns an error if the key doesn't exist.
func (s *Store) Delete(key string) error {
	return s.withLock(func() error {
		secrets, err := s.readSecrets()
		if err != nil {
			return err
		}
		if _, ok := secrets[key]; !ok {
			return fmt.Errorf("secret '%s' not found in store", key)
		}
		delete(secrets, key)
		return s.writeSecrets(secrets)
	})
}

// Import reads filePath and stores its contents as a secret.
func (s *Store) Import(key, filePath string) error {
	data, err := os.ReadFile(filePath)
	if err != nil {
		return fmt.Errorf("reading file %s: %w", filePath, err)
	}
	return s.Set(key, string(data))
}

// Resolve maps a list of SecretRefs to environment variables and Docker secret
// values. Returns an error if any referenced key is missing.
func (s *Store) Resolve(refs []config.SecretRef) (envVars map[string]string, dockerSecrets map[string]string, err error) {
	secrets, err := s.readSecrets()
	if err != nil {
		return nil, nil, err
	}

	envVars = make(map[string]string)
	dockerSecrets = make(map[string]string)

	for _, ref := range refs {
		val, ok := secrets[ref.Key]
		if !ok {
			return nil, nil, fmt.Errorf("secret '%s' not found in store", ref.Key)
		}
		switch ref.Type {
		case "env":
			envVars[ref.Target] = val
		case "docker-secret":
			dockerSecrets[ref.Target] = val
		}
	}

	return envVars, dockerSecrets, nil
}

package webhook

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"slices"
	"strings"

	"github.com/nogo/herald/internal/config"
)

const maxBodySize = 10 << 20 // 10 MB

// DeployRequest carries the information needed to trigger a deploy.
type DeployRequest struct {
	AppName  string
	App      config.App
	Repo     string
	Branch   string
	Commit   string
	CloneURL string
}

// Server is the webhook HTTP server.
type Server struct {
	Config   *config.Config
	Secret   string
	Verbose  bool
	OnDeploy func(DeployRequest) // called for each matched app; must be non-nil
}

// Handler returns the configured ServeMux.
func (s *Server) Handler() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("POST /webhook", s.handleWebhook)
	mux.HandleFunc("GET /health", s.handleHealth)
	return mux
}

func (s *Server) handleHealth(w http.ResponseWriter, r *http.Request) {
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

func (s *Server) handleWebhook(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, maxBodySize)

	body, err := io.ReadAll(r.Body)
	if err != nil {
		slog.Error("reading webhook body", "error", err)
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid payload"})
		return
	}

	eventType := r.Header.Get("X-GitHub-Event")

	if !s.verifySignature(body, r.Header.Get("X-Hub-Signature-256")) {
		slog.Info("webhook rejected",
			"event", eventType,
			"result", "rejected: invalid signature",
		)
		writeJSON(w, http.StatusForbidden, map[string]string{"error": "invalid signature"})
		return
	}

	if eventType == "ping" {
		slog.Info("webhook", "event", "ping", "result", "pong")
		writeJSON(w, http.StatusOK, map[string]string{"message": "pong"})
		return
	}

	var repo, branch, commit, cloneURL string

	switch eventType {
	case "push":
		var p PushPayload
		if err := json.Unmarshal(body, &p); err != nil {
			slog.Error("parsing push payload", "error", err)
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid payload"})
			return
		}
		repo = p.Repository.FullName
		branch = strings.TrimPrefix(p.Ref, "refs/heads/")
		commit = p.After
		cloneURL = p.Repository.CloneURL

	case "pull_request":
		var p PullRequestPayload
		if err := json.Unmarshal(body, &p); err != nil {
			slog.Error("parsing pull_request payload", "error", err)
			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid payload"})
			return
		}
		repo = p.Repository.FullName
		branch = p.PullRequest.Head.Ref
		commit = p.PullRequest.Head.SHA
		cloneURL = p.Repository.CloneURL

	default:
		slog.Info("webhook", "event", eventType, "result", "event ignored")
		writeJSON(w, http.StatusOK, map[string]string{"message": "event ignored"})
		return
	}

	if s.Verbose {
		slog.Debug("webhook payload", "event", eventType, "repo", repo, "branch", branch, "body", string(body))
	}

	var matchedNames []string
	for name, app := range s.Config.Apps {
		if app.Repo == repo && app.Branch == branch {
			matchedNames = append(matchedNames, name)
		}
	}

	if len(matchedNames) == 0 {
		slog.Info("webhook",
			"event", eventType,
			"repo", repo,
			"branch", branch,
			"result", "ignored: no matching apps",
		)
		writeJSON(w, http.StatusOK, map[string]string{"message": "no matching apps"})
		return
	}

	slices.Sort(matchedNames)

	slog.Info("webhook",
		"event", eventType,
		"repo", repo,
		"branch", branch,
		"result", fmt.Sprintf("accepted: %s", strings.Join(matchedNames, ",")),
	)

	for _, name := range matchedNames {
		app := s.Config.Apps[name]
		req := DeployRequest{
			AppName:  name,
			App:      app,
			Repo:     repo,
			Branch:   branch,
			Commit:   commit,
			CloneURL: cloneURL,
		}
		go s.OnDeploy(req)
	}

	writeJSON(w, http.StatusOK, map[string]any{
		"message": "accepted",
		"apps":    matchedNames,
	})
}

func (s *Server) verifySignature(body []byte, sigHeader string) bool {
	const prefix = "sha256="
	if !strings.HasPrefix(sigHeader, prefix) {
		return false
	}
	sigBytes, err := hex.DecodeString(sigHeader[len(prefix):])
	if err != nil {
		return false
	}
	mac := hmac.New(sha256.New, []byte(s.Secret))
	mac.Write(body)
	return hmac.Equal(mac.Sum(nil), sigBytes)
}

func writeJSON(w http.ResponseWriter, code int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(code)
	json.NewEncoder(w).Encode(v) //nolint:errcheck
}

