func TestBuildCloneURL(t *testing.T) {
	tests := []struct {
		token, repo, want string
	}{
		{"", "owner/repo", "https://github.com/owner/repo.git"},
		{"ghp_token", "owner/repo", "https://ghp_token@github.com/owner/repo.git"},
